import{_ as a,o as l,a as n,b as t}from"./app.C41L12d5.js";const A=JSON.parse('{"title":"","description":"","frontmatter":{"breadcrumbs":[{"text":"Ascend C API","link":"/api/api_list"},{"text":"SIMD API","link":"/api/SIMD-API/SIMD-API"},{"text":"基础API","link":"/api/SIMD-API/basic_api/basic_api"},{"text":"同步控制","link":"/api/SIMD-API/basic_api/sync_control/sync_control"},{"text":"核间同步","link":"/api/SIMD-API/basic_api/sync_control/inter_core_sync/inter_core_sync"},{"text":"SyncAll","link":"/api/SIMD-API/basic_api/sync_control/inter_core_sync/SyncAll"}]},"headers":[],"relativePath":"api/SIMD-API/basic_api/sync_control/inter_core_sync/SyncAll.md","filePath":"api/SIMD-API/basic_api/sync_control/inter_core_sync/SyncAll.md","outlineHeaders":[{"level":2,"title":"产品支持情况","slug":"产品支持情况","link":"#产品支持情况"},{"level":3,"title":"软同步原型","slug":"软同步原型","link":"#软同步原型"},{"level":3,"title":"硬同步（不支持config指定流水）原型","slug":"硬同步（不支持config指定流水）原型","link":"#硬同步（不支持config指定流水）原型"},{"level":3,"title":"硬同步（支持config指定流水）原型","slug":"硬同步（支持config指定流水）原型","link":"#硬同步（支持config指定流水）原型"},{"level":2,"title":"功能说明","slug":"功能说明","link":"#功能说明"},{"level":2,"title":"函数原型","slug":"函数原型","link":"#函数原型"},{"level":2,"title":"参数说明","slug":"参数说明","link":"#参数说明"},{"level":2,"title":"返回值说明","slug":"返回值说明","link":"#返回值说明"},{"level":2,"title":"约束说明","slug":"约束说明","link":"#约束说明"},{"level":2,"title":"调用示例","slug":"调用示例","link":"#调用示例"}],"lastUpdated":1788515292000}'),p={name:"api/SIMD-API/basic_api/sync_control/inter_core_sync/SyncAll.md"};function i(e,s,c,o,r,d){return l(),n("div",null,[...s[0]||(s[0]=[t(`<div><article class="markdown-body"><h1>SyncAll<a id="ZH-CN_TOPIC_0000001538296817"></a></h1><h2 id="产品支持情况">产品支持情况<a id="section1550532418810"></a><a class="header-anchor" href="#产品支持情况">​</a></h2><h3 id="软同步原型">软同步原型<a class="header-anchor" href="#软同步原型">​</a></h3><div data-filter="950"><ul><li>Ascend 950PR/Ascend 950DT：支持</li></ul></div><div data-filter="A3"><ul><li>Atlas A3 训练系列产品/Atlas A3 推理系列产品：支持</li></ul></div><div data-filter="910b"><ul><li>Atlas A2 训练系列产品/Atlas A2 推理系列产品：支持</li></ul></div><div data-filter="310b"><ul><li>Atlas 200I/500 A2 推理产品：不支持</li></ul></div><div data-filter="310p"><ul><li>Atlas 推理系列产品AI Core：支持</li></ul></div><div data-filter="310p"><ul><li>Atlas 推理系列产品Vector Core：不支持</li></ul></div><div data-filter="910"><ul><li>Atlas 训练系列产品：支持</li></ul></div><div data-filter="x90"><ul><li>Kirin X90：支持</li></ul></div><div data-filter="9030"><ul><li>Kirin 9030：支持</li></ul></div><h3 id="硬同步（不支持config指定流水）原型">硬同步（不支持config指定流水）原型<a class="header-anchor" href="#硬同步（不支持config指定流水）原型">​</a></h3><div data-filter="950"><ul><li>Ascend 950PR/Ascend 950DT：支持</li></ul></div><div data-filter="A3"><ul><li>Atlas A3 训练系列产品/Atlas A3 推理系列产品：支持</li></ul></div><div data-filter="910b"><ul><li>Atlas A2 训练系列产品/Atlas A2 推理系列产品：支持</li></ul></div><div data-filter="310b"><ul><li>Atlas 200I/500 A2 推理产品：不支持</li></ul></div><div data-filter="310p"><ul><li>Atlas 推理系列产品AI Core：不支持</li></ul></div><div data-filter="310p"><ul><li>Atlas 推理系列产品Vector Core：不支持</li></ul></div><div data-filter="910"><ul><li>Atlas 训练系列产品：不支持</li></ul></div><div data-filter="x90"><ul><li>Kirin X90：支持</li></ul></div><div data-filter="9030"><ul><li>Kirin 9030：支持</li></ul></div><h3 id="硬同步（支持config指定流水）原型">硬同步（支持config指定流水）原型<a class="header-anchor" href="#硬同步（支持config指定流水）原型">​</a></h3><div data-filter="950"><ul><li>Ascend 950PR/Ascend 950DT：支持</li></ul></div><div data-filter="A3"><ul><li>Atlas A3 训练系列产品/Atlas A3 推理系列产品：不支持</li></ul></div><div data-filter="910b"><ul><li>Atlas A2 训练系列产品/Atlas A2 推理系列产品：不支持</li></ul></div><div data-filter="310b"><ul><li>Atlas 200I/500 A2 推理产品：不支持</li></ul></div><div data-filter="310p"><ul><li>Atlas 推理系列产品AI Core：不支持</li></ul></div><div data-filter="310p"><ul><li>Atlas 推理系列产品Vector Core：不支持</li></ul></div><div data-filter="910"><ul><li>Atlas 训练系列产品：不支持</li></ul></div><div data-filter="x90"><ul><li>Kirin X90：不支持</li></ul></div><div data-filter="9030"><ul><li>Kirin 9030：不支持</li></ul></div><h2 id="功能说明">功能说明<a id="section618mcpsimp"></a><a class="header-anchor" href="#功能说明">​</a></h2><p>头文件路径为：<code>&quot;basic_api/kernel_operator_block_sync_intf.h&quot;</code>。</p><p>SyncAll是核间同步控制接口，根据不同的函数原型介绍其功能：</p><ul><li><p>硬件同步接口： 用于多个核之间的同步控制，支持以下同步场景：</p><ul><li>纯Vector算子的全核同步，可参考<a href="key_features.html#ZH-CN_TOPIC_0000002586300741">CrossCoreSetFlag的模式0</a>。</li><li>融合算子的全核同步，一次性实现三个核间同步能力（参考<a href="key_features.html#ZH-CN_TOPIC_0000002586300741">CrossCoreSetFlag的关键特性说明</a>）：首先完成单个AI Core内，AIC与所有AIV同步（AIC等AIV）；接着完成多个AI Core间，所有AIC的同步；最后完成单个AI Core内，所有AIV与AIC同步（AIV等AIC）。</li></ul></li><li><p>软件同步接口： 仅支持纯Vector算子的多核（参与同步的核数可通过入参指定）同步。每一个AIV都向全局内存对应位置写入信号值1，接着每一个AIV都持续轮询全局内存中所有AIV对应的信号值，直到所有AIV核对应的信号值都变为1。</p></li></ul><p>在纯Vector算子场景中，若所有AIV核默认参与同步，推荐采用性能更优的硬件同步接口；若需指定部分AIV核参与同步，则应使用软件同步接口，并通过入参usedCores完成配置。</p><h2 id="函数原型">函数原型<a id="section620mcpsimp"></a><a class="header-anchor" href="#函数原型">​</a></h2><ul><li><p>软同步</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="k">template</span><span class="w"> </span><span class="o">&lt;</span><span class="kt">bool</span><span class="w"> </span><span class="n">isAIVOnly</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="nb">true</span><span class="o">&gt;</span>
<span class="n">__aicore__</span><span class="w"> </span><span class="kr">inline</span><span class="w"> </span><span class="kt">void</span><span class="w"> </span><span class="n">SyncAll</span><span class="p">(</span><span class="k">const</span><span class="w"> </span><span class="n">GlobalTensor</span><span class="o">&lt;</span><span class="kt">int32_t</span><span class="o">&gt;&amp;</span><span class="w"> </span><span class="n">gmWorkspace</span><span class="p">,</span><span class="w"> </span><span class="k">const</span><span class="w"> </span><span class="n">LocalTensor</span><span class="o">&lt;</span><span class="kt">int32_t</span><span class="o">&gt;&amp;</span><span class="w"> </span><span class="n">ubWorkspace</span><span class="p">,</span><span class="w"> </span><span class="k">const</span><span class="w"> </span><span class="kt">int32_t</span><span class="w"> </span><span class="n">usedCores</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">0</span><span class="p">)</span>
</code></pre></div></li><li><p>硬同步</p><ul><li><p>不支持config指定流水</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="k">template</span><span class="w"> </span><span class="o">&lt;</span><span class="kt">bool</span><span class="w"> </span><span class="n">isAIVOnly</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="nb">true</span><span class="o">&gt;</span>
<span class="n">__aicore__</span><span class="w"> </span><span class="kr">inline</span><span class="w"> </span><span class="kt">void</span><span class="w"> </span><span class="n">SyncAll</span><span class="p">()</span>
</code></pre></div></li><li><p>支持config指定流水</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="k">template</span><span class="w"> </span><span class="o">&lt;</span><span class="kt">bool</span><span class="w"> </span><span class="n">isAIVOnly</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="nb">true</span><span class="p">,</span><span class="w"> </span><span class="k">const</span><span class="w"> </span><span class="n">SyncAllConfig</span><span class="o">&amp;</span><span class="w"> </span><span class="n">config</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">DEFAULT_SYNC_ALL_CONFIG</span><span class="o">&gt;</span>
<span class="n">__aicore__</span><span class="w"> </span><span class="kr">inline</span><span class="w"> </span><span class="kt">void</span><span class="w"> </span><span class="n">SyncAll</span><span class="p">()</span>
</code></pre></div></li></ul></li></ul><h2 id="参数说明">参数说明<a id="section622mcpsimp"></a><a class="header-anchor" href="#参数说明">​</a></h2><p><strong>表1</strong> 模板参数说明</p><table><thead><tr><th>参数名</th><th>描述</th></tr></thead><tbody><tr><td>isAIVOnly</td><td>控制SyncAll作用于纯Vector算子或Mix（包含Cube和Vector计算）算子。可选值：<br>• <strong>true</strong>（默认值）：纯Vector算子的全核同步，仅执行Vector核的全核同步。<br>• <strong>false</strong>：Mix（包含Cube和Vector计算）算子的全核同步，先分别完成Vector核和Cube核的全核同步，再执行两者之间的同步（软同步接口不支持此功能）。</td></tr><tr><td>config</td><td><strong>该配置仅当isAIVOnly=True时有效。</strong><br>struct SyncAllConfig { pipe_t triggerPipe; pipe_t waitPipe; }; // 默认使用全部流水来进行触发和等待行为。<br>constexpr SyncAllConfig DEFAULT_SYNC_ALL_CONFIG = {PIPE_ALL, PIPE_ALL};<br>控制SyncAll函数的行为，在多个AI Core之间进行流水同步时，指定哪些流水（pipe）用于触发和等待。<br>• <strong>triggerPipe</strong>：指定哪个流水用于“发送触发信号”。仅支持MTE2、MTE3、PIPE_ALL。<br>• <strong>waitPipe</strong>：指定哪个流水用于“接收等待信号”。仅支持MTE2、MTE3、PIPE_ALL。<br>// 多个AIV进行计算 <br>Compute(); <br>// 多个AIV将计算结果搬出到GM <br>CopyToGM(); <br>// 等待所有数据拷贝到GM后，进行累加 <br>constexpr AscendC::SyncAllConfig CustomConfig = {PIPE_MTE3, PIPE_ALL}; <br>AscendC::SyncAll&lt;true, CustomConfig&gt;(); <br>for (int i = 0; i &lt; blockNum; i++) { <br> if (i != blockIdx) { <br> CopyFromGm(); <br> Accumulate(); <br> } <br>} <br>// 累加后的数据写回 <br>CopyToGm();</td></tr></tbody></table><p><strong>表2</strong> 参数说明</p><table><thead><tr><th>参数名称</th><th>输入/输出</th><th>含义</th></tr></thead><tbody><tr><td>gmWorkspace</td><td>输入</td><td>gmWorkspace为用户定义的全局空间，作为所有核共用的缓存，用于保存每个核的状态标记，类型为GlobalTensor，支持的数据类型为int32_t。GlobalTensor数据结构的定义请参考<a href="../../data_structures/GlobalTensor/GlobalTensor.html">GlobalTensor</a>。<br>所需空间大小和使用注意项参见<a href="#section633mcpsimp">约束说明</a>。<br>硬同步接口不支持该参数。</td></tr><tr><td>ubWorkspace</td><td>输入</td><td>ubWorkspace为用户定义的局部空间，每个核单独自用，用于标记当前核的状态。<br>类型为<a href="../../data_structures/LocalTensor/LocalTensor.html">LocalTensor</a>，支持的TPosition为VECIN、VECCALC、VECOUT，支持的数据类型为int32_t。<br>所需空间大小参见<a href="#section633mcpsimp">约束说明</a>。<br>硬同步接口不支持该参数。</td></tr><tr><td>usedCores</td><td>输入</td><td>指定多少个核之间的同步，传入数值不能超过算子调用时指定的逻辑numBlocks。此参数为默认参数，不传此参数表示全核软同步。<br>仅在软同步接口中支持，硬同步接口不支持该参数。</td></tr></tbody></table><h2 id="返回值说明">返回值说明<a id="section91032023123812"></a><a class="header-anchor" href="#返回值说明">​</a></h2><p>无</p><h2 id="约束说明">约束说明<a id="section633mcpsimp"></a><a class="header-anchor" href="#约束说明">​</a></h2><p>SyncAll硬件同步和软件同步接口的内部实现不同，约束条件也有所区别。</p><ul><li><p>软件同步接口约束：</p><ul><li>gmWorkspace缓存申请的空间大小要求大于等于GetBlockNum()*32Bytes，并且缓存的值需要初始化为0。目前常见的有两种初始化方式： <ul><li>通过在host侧进行初始化操作，确保传入该接口时，gmWorkspace缓存已经初始化为0；</li><li>在kernel侧初始化的时候对gmWorkspace缓存初始化，需要注意的是，每个核上都需要初始化全部的gmWorkspace缓存空间。</li></ul></li><li>ubWorkspace申请的空间大小要求大于等于GetBlockNum()*32Bytes。</li><li>在纯Vector算子场景中，若所有AIV核默认参与同步，推荐采用性能更优的硬件同步接口；若需指定部分AIV核参与同步，则应使用软件同步接口，并通过入参usedCores完成配置。</li><li>usedCores传入数值不能超过算子调用时指定的逻辑AI Core中AIV的数量：GetBlockNum()*GetTaskRatio()，不传此参数表示全核软同步。</li></ul></li><li><p>硬件同步接口约束：</p><ul><li><p>使用硬同步接口时，需根据场景使用合适的核函数（Kernel）修饰符：</p><ul><li>在纯Vector算子，需使用__mix__(0, 1)修饰核函数（Kernel），而不是使用__vector__，具体原因请参考<a href="CrossCoreSetFlag_ISASI.html#%E7%BA%A6%E6%9D%9F%E8%AF%B4%E6%98%8E">CrossCoreSetFlag约束说明</a>中的核函数（Kernel）类型配置说明。</li><li>对于Mix（包含Cube和Vector计算）算子，需使用__mix__(1, 1)或__mix__(1, 2)修饰核函数（Kernel）。</li></ul></li><li><p>对于纯Vector算子，模板参数isAIVOnly必须设置为true，否则会导致程序卡死。</p></li><li><p>对于Mix（包含Cube和Vector计算）算子，模板参数isAIVOnly设置为true，会导致接口实际只能完成Vector全核同步与预期同步行为不符。</p></li><li><p>使用该接口时，建议开启batchmode模式，使算子独占全部所需核资源，否则可能因满足以下条件导致死锁：</p><ul><li>多流并发场景（≥2条执行流）。</li><li>≥2个算子并发执行。</li><li>所有并发算子的核数总和超过物理核数。</li><li>≥2个并发算子使用了核间同步功能。</li></ul><p>具体而言，在多流场景下，某条流的核间同步算子虽分配到n个物理核，但可能仅有n-m个核先被调度执行，而其余m个核因被其他流的核间同步算子抢占而尚未启动。先启动的n-m个核执行到核间同步时等待剩余m核完成，而剩余m核因被其他流的核间同步算子占用而无法释放，形成死锁。 核函数（Kernel）直调场景下通过<a href="../../../../../guide/programming_guide/language_extension/simd_builtin_keywords.html">__schedmode__(mode)</a>限定符来设置batchmode模式；工程化算子开发场景下，通过TilingContext的SetScheduleMode接口来设置batchmode模式，具体请参考<a href="https://www.hiascend.com/document/detail/zh/CANNCommunityEdition/900beta2/API/basicdataapi/atlasopapi_07_00001.html">《基础数据结构和接口》</a>。 <a id="syncall_flagId冲突说明"></a></p></li><li><p>SyncAll硬件同步接口内部实现中使用了<a href="CrossCoreSetFlag_ISASI.html">CrossCoreSetFlag</a>和<a href="CrossCoreWaitFlag_ISASI.html">CrossCoreWaitFlag</a>进行核间同步控制，因此开发者同时使用CrossCoreSetFlag（或CrossCoreWaitFlag）和SyncAll硬件同步接口时，需注意避免以下<a href="CrossCoreSetFlag_ISASI.html#flagId%E5%8F%96%E5%80%BC%E8%8C%83%E5%9B%B4%E8%AF%B4%E6%98%8E">flagId</a>冲突：</p><div data-filter="950"><ul><li><p>针对<a href="../../../../../guide/programming_guide/language_extension/simd_builtin_keywords.html">NPU架构版本3510</a>，SyncAll硬件同步接口的flagId占用情况如表3所示：</p><p><strong>表3</strong> SyncAll硬件同步接口flagId占用情况</p><table><thead><tr><th align="left">SyncAll 使用场景</th><th align="left">占用flagId汇总</th><th align="left">各计算核flagId占用情况</th></tr></thead><tbody><tr><td align="left">isAIVOnly=true</td><td align="left">14</td><td align="left">AIV：14</td></tr><tr><td align="left">isAIVOnly=false（核函数（Kernel）使用<code>__mix__(1, 1)</code>修饰时）</td><td align="left">11、12、13</td><td align="left">AIC：11、12、13；AIV：12、13</td></tr><tr><td align="left">isAIVOnly=false（核函数（Kernel）使用<code>__mix__(1, 2)</code>修饰时）</td><td align="left">11、12、13、28、29</td><td align="left">AIC：11、12、13、28、29；AIV：12、13</td></tr></tbody></table></li></ul></div><div data-filter="A3,910b"><ul><li><p>针对<a href="../../../../../guide/programming_guide/language_extension/simd_builtin_keywords.html">NPU架构版本2201</a>，SyncAll硬件同步接口的flagId占用情况如表4所示：</p><p><strong>表4</strong> SyncAll硬件同步接口flagId占用情况</p><table><thead><tr><th align="left">SyncAll 使用场景</th><th align="left">占用flagId汇总</th><th align="left">各计算核flagId占用情况</th></tr></thead><tbody><tr><td align="left">isAIVOnly=true</td><td align="left">14</td><td align="left">AIV：14</td></tr><tr><td align="left">isAIVOnly=false</td><td align="left">11、12、13</td><td align="left">AIC：11、12、13；AIV：12、13</td></tr></tbody></table></li></ul></div></li></ul></li><li><p>硬件同步接口和软件同步接口公共约束：使用该接口进行多核控制时，算子调用时指定的逻辑AI Core核数numBlocks必须保证不大于实际运行该算子的AI处理器核数，否则框架进行多轮调度时会插入异常同步，导致核函数（Kernel）“卡死”现象。</p></li></ul><h2 id="调用示例">调用示例<a id="section642mcpsimp"></a><a class="header-anchor" href="#调用示例">​</a></h2><p>本示例实现功能为使用8个核进行数据处理，每个核均是处理32个float类型数据，对该数据乘2后再与其他核上进行同样乘2的数据进行相加，中间结果保存到workGm，因此多个核之间需要进行数据同步。此样例中，使用软同步，入口函数传入的syncGm里的值都已经在host侧初始化为0。若以下用例改成使用硬同步，则不需要传入syncGm，并且不需要使用workQueue。</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="c1">// syncGlobal为用户定义的全局空间，作为所有核共用的缓存，类型为GlobalTensor；workLocal为用户定义的局部空间，每个核单独自用，类型为LocalTensor。</span>
<span class="kt">int</span><span class="w"> </span><span class="n">srcDataSize</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">256</span><span class="p">;</span><span class="w"> </span><span class="c1">// 参与计算的元素个数。</span>
<span class="kt">int32_t</span><span class="w"> </span><span class="n">blockNum</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">AscendC</span><span class="o">::</span><span class="n">GetBlockNum</span><span class="p">();</span><span class="w"> </span><span class="c1">// 获取核总数。</span>
<span class="kt">int32_t</span><span class="w"> </span><span class="n">blockIdx</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">AscendC</span><span class="o">::</span><span class="n">GetBlockIdx</span><span class="p">();</span><span class="w"> </span><span class="c1">// 获取当前工作的核ID。</span>
<span class="kt">uint32_t</span><span class="w"> </span><span class="n">perBlockSize</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">srcDataSize</span><span class="w"> </span><span class="o">/</span><span class="w"> </span><span class="n">blockNum</span><span class="p">;</span><span class="w"> </span><span class="c1">// 每个核平分处理相同个数。</span>
<span class="c1">// 当前工作核计算后的数据先保存到外部工作空间，workGlobal为GlobalTensor，dstLocal为LocalTensor。</span>
<span class="n">AscendC</span><span class="o">::</span><span class="n">DataCopy</span><span class="p">(</span><span class="n">workGlobal</span><span class="p">[</span><span class="n">blockIdx</span><span class="w"> </span><span class="o">*</span><span class="w"> </span><span class="n">perBlockSize</span><span class="p">],</span><span class="w"> </span><span class="n">dstLocal</span><span class="p">,</span><span class="w"> </span><span class="n">perBlockSize</span><span class="p">);</span>
<span class="c1">// 等待所有核都完成计算。</span>
<span class="n">AscendC</span><span class="o">::</span><span class="n">SyncAll</span><span class="p">(</span><span class="n">syncGlobal</span><span class="p">,</span><span class="w"> </span><span class="n">workLocal</span><span class="p">);</span>
</code></pre></div><p>完整样例请参考<a href="https://gitcode.com/cann/asc-devkit/tree/master/examples/01_simd_cpp_api/03_basic_api/05_sync_control/sync_all">SyncAll样例</a>。</p></article></div>`,1)])])}const u=a(p,[["render",i]]);export{A as __pageData,u as default};
